<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
const ready=ref(false),items=ref<any[]>([]),detail=ref<any>(null),genres=ref<any[]>([]),keyword=ref(''),genre=ref(''),year=ref(''),busy=ref(false),error=ref(''),selected=ref(''),dataset=ref(''),source=ref('tmdb'),external=ref('278'),offset=ref(0)
let serial=0
async function request(path:string){const r=await fetch('/api/catalog/'+path);const b=await r.json();if(!r.ok)throw new Error(r.status===404?'没有找到这部电影。':r.status===400?'条件无效，请检查年份或外部 ID。':'目录暂时不可用，请重试。');return b.data}
async function load(){if(!ready.value)return;const id=++serial;busy.value=true;error.value='';try{if(selected.value){const data=await request('movies/'+encodeURIComponent(selected.value));if(id===serial)detail.value=data}else{const params=new URLSearchParams({limit:'6',offset:String(offset.value),sort:'id'});if(keyword.value)params.set('keyword',keyword.value);if(genre.value)params.set('genre_id',genre.value);if(year.value){params.set('year_from',year.value);params.set('year_to',year.value)}const data=await request('movies?'+params);if(id===serial)items.value=data.items}}catch(e){if(id===serial){error.value=(e as Error).message;detail.value=null;items.value=[]}}finally{if(id===serial)busy.value=false}}
function route(){selected.value=location.hash.startsWith('#movie/')?location.hash.slice(7):'';detail.value=null;load()}
function search(){offset.value=0;load()}
async function lookup(){error.value='';try{const m=await request('lookup?'+new URLSearchParams({source:source.value,external_id:external.value}));location.hash='movie/'+m.movie_id}catch(e){error.value=(e as Error).message}}
onMounted(async()=>{window.addEventListener('hashchange',route);try{const info=await fetch('/api/catalog/demo-info').then(r=>r.json());if(info.mode!=='LOCAL_AUTHORIZED_TMDB_NONCOMMERCIAL')throw Error('来源模式不匹配，停止展示。');dataset.value=info.dataset_id;ready.value=true;genres.value=(await request('genres')).items;route()}catch(e){error.value=(e as Error).message;items.value=[]}})
onUnmounted(()=>window.removeEventListener('hashchange',route))
</script>
<template>
<div class="real-shell"><header><a class="brand" href="/real-catalog.html">MovieInsight</a><span class="source">LOCAL AUTHORIZED · TMDB</span></header>
<main><nav aria-label="目录导航"><a href="#">真实电影目录</a><a href="http://127.0.0.1:5175/catalog.html">合成推荐演示（独立数据）</a><a href="#credits" @click.prevent="($refs.credits as HTMLElement)?.scrollIntoView()">来源与署名</a></nav>
<div class="intro"><h1>从真实电影，开始探索。</h1><p>TMDB 官方 API 元数据 · 非商业毕业设计样本 · 本地只读目录</p><p class="boundary">真实登录与 MySQL 未接入；此目录不接受演示用户行为。</p></div>
<form v-if="!selected" class="filters" @submit.prevent="search"><label>电影名称<input v-model="keyword" placeholder="搜索已导入样本"></label><label>上映年份<input v-model="year" inputmode="numeric" placeholder="不限"></label><label>类型<select v-model="genre"><option value="">全部类型</option><option v-for="g in genres" :key="g.genre_id" :value="String(g.genre_id)">{{g.name_zh}}</option></select></label><button :disabled="busy">查找电影</button></form>
<details v-if="!selected" class="lookup"><summary>通过外部 ID 定位</summary><form @submit.prevent="lookup"><label>来源<select v-model="source"><option>tmdb</option><option>imdb</option><option>douban</option><option>wikidata</option></select></label><label>外部 ID<input v-model="external"></label><button>定位电影</button></form></details>
<a v-if="selected" class="back" href="#">返回真实电影目录</a>
<div v-if="busy" role="status" class="state">正在读取本地目录…</div><div v-else-if="error" role="alert" class="state"><h2>暂时无法展示</h2><p>{{error}}</p><button @click="load">重试</button></div>
<article v-else-if="selected&&detail" class="detail"><div class="placeholder"><small>未下载海报</small><strong>{{detail.title}}</strong><span>来源：TMDB</span></div><div><p class="meta">{{detail.release_year??'年份未提供'}} · {{detail.runtime_minutes??'片长未提供'}} 分钟 · {{detail.original_language??'语言未提供'}}</p><h2>{{detail.title}}</h2><p>{{detail.original_title}}</p><div class="tags"><span v-for="g in detail.genres" :key="g.genre_id">{{g.name_zh}}</span></div><h3>故事简介</h3><p class="overview">{{detail.overview||'来源未提供简介。'}}</p><h3>来源评分</h3><p v-if="!detail.ratings.length">来源未提供评分。</p><p v-for="r in detail.ratings" :key="r.source">{{r.source}} · {{r.score_value??'未提供'}} / {{r.score_scale}} · {{r.vote_count??'票数未知'}} 票<br><small>截至 {{r.observed_at}} · 源精度按半入规则保留两位小数</small></p><h3>外部标识</h3><p v-for="id in detail.external_ids" :key="id.source">{{id.source}} · {{id.external_id}}</p><p class="meta">IMDb 标识为 TMDB 声明，未调用 IMDb 接口核实。</p></div></article>
<template v-else><div class="section-title"><h2>已导入电影</h2><span>{{items.length}} 部当前样本</span></div><section v-if="items.length" class="grid"><a v-for="m in items" :key="m.movie_id" :href="'#movie/'+m.movie_id" class="movie"><div class="placeholder"><small>未下载海报</small><strong>{{m.title}}</strong><span>TMDB 官方元数据</span></div><h3>{{m.title}}</h3><p>{{m.release_year??'年份未提供'}} · {{m.runtime_minutes??'片长未提供'}} 分钟</p></a></section><div v-else class="state"><h2>没有匹配的电影</h2><p>当前仅展示已核验的小样本，请尝试其他条件。</p></div><div class="pages"><button :disabled="!offset||busy" @click="offset-=6;load()">上一页</button><span>第 {{offset/6+1}} 页</span><button :disabled="items.length<6||busy" @click="offset+=6;load()">下一页</button></div></template>
<section id="credits" ref="credits" class="credits"><h2>来源与署名</h2><a href="https://www.themoviedb.org/" target="_blank" rel="noopener"><img src="/tmdb/attribution.svg" alt="TMDB" width="100"></a><p>This product uses the TMDB API but is not endorsed or certified by TMDB.</p><p>仅用于非商业毕业设计。元数据来自官方电影详情接口；未下载海报、未生成评分、未将合成数据混入目录。<a href="https://developer.themoviedb.org/docs/faq" target="_blank" rel="noopener">使用与署名说明</a></p><p class="meta">目录版本 {{dataset?dataset.slice(0,16):'未确认'}} · REAL-PRODUCTION-UNVERIFIED</p></section>
</main><footer>MovieInsight · 真实元数据本地样本 · 与合成推荐及认证数据库隔离</footer></div>
</template>
<style scoped>
:global(body){margin:0;background:#15191d;color:#f2eee5;font-family:"Segoe UI","Microsoft YaHei",sans-serif}:global(*){box-sizing:border-box}:global(a){color:inherit;text-underline-offset:5px}:global(button),:global(input),:global(select){font:inherit}:global(:focus-visible){outline:2px solid #e2ba75;outline-offset:4px}:global(::selection){background:#78532b;color:white}header{display:flex;justify-content:space-between;align-items:center;padding:24px 5vw;border-bottom:1px solid #384047}.brand{font-size:24px;font-weight:700;text-decoration:none}.source{color:#e2ba75;font-size:12px;border:1px solid #7d6846;padding:8px 12px}main{max-width:1320px;margin:auto;padding:36px 5vw}nav{display:flex;gap:24px;flex-wrap:wrap;margin-bottom:42px;color:#e2ba75;font-size:14px}h1{font-size:clamp(28px,3vw,38px);font-weight:600;margin:0 0 16px}.intro p{color:#c0c8cd;line-height:1.7}.boundary{font-size:12px}.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:14px;align-items:end;padding:24px 0;border-block:1px solid #384047;margin-top:30px}label{display:flex;flex-direction:column;gap:8px;font-size:12px;color:#c0c8cd}input,select{width:100%;min-width:0;background:#20272d;color:#f1ede5;border:1px solid #49545d;border-radius:4px;padding:11px}button{background:#dfba7f;color:#241d13;border:0;border-radius:4px;padding:12px 18px;cursor:pointer;font-weight:600}button:hover:not(:disabled){background:#f0cf98}button:disabled{opacity:.45;cursor:default}.lookup{margin:24px 0;color:#c0c8cd}.lookup summary{cursor:pointer}.lookup form{display:flex;gap:12px;align-items:end;margin-top:16px}.lookup label{max-width:250px}.section-title{display:flex;justify-content:space-between;align-items:center;margin-top:30px}.section-title span,.meta{font-size:12px;color:#bbc4c9}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.movie{text-decoration:none}.placeholder{height:300px;background:#202a31;border:1px solid #52616b;display:flex;flex-direction:column;justify-content:space-between;padding:28px}.placeholder strong{font-size:30px;line-height:1.5;font-weight:500;max-width:9em}.placeholder small,.placeholder span{font-size:12px;color:#bbc4c9}.movie:hover .placeholder{border-color:#e2ba75}.movie h3{font-size:18px;font-weight:500}.movie p{color:#bbc4c9;font-size:13px}.pages{display:flex;gap:20px;justify-content:center;align-items:center;margin:35px 0}.pages span{font-size:13px}.detail{display:grid;grid-template-columns:300px 1fr;gap:48px;margin-top:32px}.detail .placeholder{height:430px}.detail h2{font-size:34px}.detail h3{margin-top:30px;font-size:16px}.detail p{line-height:1.8;color:#c5cdd1}.detail small{font-size:12px}.overview{max-width:68ch}.tags{display:flex;gap:8px;flex-wrap:wrap}.tags span{border:1px solid #62707b;padding:5px 10px;font-size:12px}.state{padding:64px 20px;text-align:center;min-height:240px;color:#c3cbd0}.credits{border-top:1px solid #384047;padding-top:28px;margin-top:48px}.credits h2{font-size:20px}.credits img{width:100px;height:auto}.credits p{font-size:12px;line-height:1.8;color:#c0c8cd;max-width:85ch}footer{border-top:1px solid #384047;text-align:center;padding:28px;font-size:12px;color:#b3bec4}@media(max-width:850px){.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.detail{grid-template-columns:1fr}.detail .placeholder{max-width:300px}.lookup form{flex-wrap:wrap}}@media(max-width:500px){header{padding:20px;gap:12px}.brand{font-size:20px}.source{font-size:9px;padding:7px}main{padding:28px 20px}nav{gap:18px}.filters{display:flex;flex-direction:column;align-items:stretch}.grid{grid-template-columns:1fr}.placeholder{height:280px}.detail{gap:25px}.detail .placeholder{height:300px;max-width:none}.detail h2{font-size:28px}.pages{gap:12px}.pages button{padding:10px 14px}}
</style>
